/// ASN.1 `AMF-TNLAssociationToAddItem` (NGAP-IEs).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AmfTnlAssociationToAddItem {
    /// `aMF-TNLAssociationAddress`
    pub amf_tnl_association_address: CpTransportLayerInformation,
    /// `tNLAssociationUsage`
    pub tnl_association_usage: Option<TnlAssociationUsage>,
    /// `tNLAddressWeightFactor`
    pub tnl_address_weight_factor: TnlAddressWeightFactor,
    /// `iE-Extensions`
    pub ie_extensions: Option<rt::ie::UnknownIes>,
}

impl AmfTnlAssociationToAddItem {
    /// A value with the mandatory components given and every optional one absent.
    pub fn new(amf_tnl_association_address: CpTransportLayerInformation, tnl_address_weight_factor: TnlAddressWeightFactor) -> Self {
        Self {
            amf_tnl_association_address,
            tnl_association_usage: None,
            tnl_address_weight_factor,
            ie_extensions: None,
        }
    }
}

impl rt::AperEncode for AmfTnlAssociationToAddItem {
    fn aper_encode(&self, w: &mut rt::BitWriter) -> rt::Result<()> {
        w.write_bit(false); // extension marker: no additions
        w.write_bit(self.tnl_association_usage.is_some());
        w.write_bit(self.ie_extensions.is_some());
        {
            let x = &self.amf_tnl_association_address;
            x.aper_encode(w)?;
        }
        if let Some(x) = &self.tnl_association_usage {
            x.aper_encode(w)?;
        }
        {
            let x = &self.tnl_address_weight_factor;
            x.aper_encode(w)?;
        }
        if let Some(x) = &self.ie_extensions {
            rt::ie::write_container(w, rt::Size::range(1, 65535), &x.ies)?;
        }
        Ok(())
    }
}

impl rt::AperDecode for AmfTnlAssociationToAddItem {
    fn aper_decode(r: &mut rt::BitReader<'_>) -> rt::Result<Self> {
        let extension = r.read_bit()?;
        let p_tnl_association_usage = r.read_bit()?;
        let p_ie_extensions = r.read_bit()?;
        let v_amf_tnl_association_address = <CpTransportLayerInformation>::aper_decode(r)?;
        let v_tnl_association_usage = if p_tnl_association_usage { Some(<TnlAssociationUsage>::aper_decode(r)?) } else { None };
        let v_tnl_address_weight_factor = <TnlAddressWeightFactor>::aper_decode(r)?;
        let v_ie_extensions = if p_ie_extensions { Some(rt::ie::read_container(r, rt::Size::range(1, 65535)).map(|ies| { ies.iter().for_each(rt::ie::note_unknown); rt::ie::UnknownIes { ies } })?) } else { None };
        if extension {
            r.read_extension_additions()?;
        }
        Ok(Self {
            amf_tnl_association_address: v_amf_tnl_association_address,
            tnl_association_usage: v_tnl_association_usage,
            tnl_address_weight_factor: v_tnl_address_weight_factor,
            ie_extensions: v_ie_extensions,
        })
    }
}

