/// The extension IEs of `AMF-TNLAssociationToRemoveItem-ExtIEs` (NGAP-IEs). IEs not defined here are kept in `unknown_ies`.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct AmfTnlAssociationToRemoveItemExtIes {
    /// `id-TNLAssociationTransportLayerAddressNGRAN` (id 168, Reject, Optional)
    pub tnl_association_transport_layer_address_ngran: Option<CpTransportLayerInformation>,
    /// IEs this version of the specification does not define here, as received (id, criticality, encoded value).
    pub unknown_ies: Vec<rt::ie::RawIe>,
}

impl AmfTnlAssociationToRemoveItemExtIes {
    /// A value with the mandatory IEs given and every optional one absent.
    pub fn new() -> Self {
        Self {
            tnl_association_transport_layer_address_ngran: None,
            unknown_ies: Vec::new(),
        }
    }
}

impl rt::AperEncode for AmfTnlAssociationToRemoveItemExtIes {
    fn aper_encode(&self, w: &mut rt::BitWriter) -> rt::Result<()> {
        let mut ies: Vec<rt::ie::RawIe> = Vec::new();
        if let Some(x) = &self.tnl_association_transport_layer_address_ngran {
            ies.push(rt::ie::RawIe::new(168, rt::ie::Criticality::Reject, x)?);
        }
        ies.extend(self.unknown_ies.iter().cloned());
        rt::ie::write_container(w, rt::Size::range(1, 65535), &ies)
    }
}

impl rt::AperDecode for AmfTnlAssociationToRemoveItemExtIes {
    fn aper_decode(r: &mut rt::BitReader<'_>) -> rt::Result<Self> {
        let mut s_tnl_association_transport_layer_address_ngran: Option<CpTransportLayerInformation> = None;
        let mut unknown_ies = Vec::new();
        for ie in rt::ie::read_container(r, rt::Size::range(1, 65535))? {
            match ie.id {
                168 => rt::ie::set_once(&mut s_tnl_association_transport_layer_address_ngran, 168, ie.decode()?)?,
                _ => {
                    rt::ie::note_unknown(&ie);
                    unknown_ies.push(ie)
                }
            }
        }
        Ok(Self {
            tnl_association_transport_layer_address_ngran: s_tnl_association_transport_layer_address_ngran,
            unknown_ies,
        })
    }
}
